.hno2-root{position:absolute;inset:0;overflow:hidden;background:var(--wa-bg, #05050a);z-index:5;font-family:"Pretendard","Pretendard Variable","Malgun Gothic",-apple-system,system-ui,sans-serif;font-size:16px;font-weight:400;font-style:normal;line-height:normal;letter-spacing:normal;color:var(--wa-text, #fff);text-align:left;text-transform:none;word-spacing:normal;-webkit-font-smoothing:antialiased}
.hno2-root,.hno2-root *,.hno2-root *::before,.hno2-root *::after{box-sizing:border-box}
.hno2-root *{margin:0;padding:0;border:0 solid transparent;background:none;font:inherit;color:inherit;text-decoration:none}
.hno2-root img{display:block;border:0;max-width:none}
.hno2-root [hidden]{display:none!important}
.hno2-root .n1_7853{word-break:break-word;grid-column:1;align-content:stretch;display:flex;font-family:"Pretendard","Pretendard Variable","Malgun Gothic",-apple-system,system-ui,sans-serif;font-weight:600;gap:8px;height:22px;align-items:center;justify-content:center;line-height:normal;margin-left:132px;margin-top:0;font-style:normal;padding-left:12px;padding-right:12px;padding-top:5.7px;padding-bottom:5.7px;position:relative;border-radius:40px;grid-row:1;font-size:14px;width:137px;white-space:nowrap;border-style:solid;border-color:var(--wa-line, #566761);border-width:1px;background-image:linear-gradient(90deg, color-mix(in srgb, var(--wa-bg, rgb(0 0 0)) 30%, transparent) 0%, color-mix(in srgb, var(--wa-bg, rgb(0 0 0)) 30%, transparent) 100%), linear-gradient(90deg, color-mix(in srgb, var(--wa-surface, rgb(59 76 70)) 20%, transparent) 0%, color-mix(in srgb, var(--wa-surface, rgb(59 76 70)) 20%, transparent) 100%)}
